INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (1, 23, N'The manager sent the meeting agenda yesterday.', N'Người quản lý đã gửi chương trình cuộc họp vào hôm qua.', NULL, CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset), CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (2, 24, N'I have an appointment with the client at 10 a.m.', N'Tôi có lịch hẹn với khách hàng lúc 10 giờ sáng.', NULL, CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset), CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (3, 25, N'Please arrange a conference room for the interview.', N'Vui lòng sắp xếp phòng họp cho buổi phỏng vấn.', NULL, CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset), CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (4, 26, N'All team members are expected to attend the training.', N'Tất cả thành viên nhóm được yêu cầu tham dự buổi đào tạo.', NULL, CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset), CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (5, 27, N'The director gave a brief update on sales.', N'Giám đốc đưa ra cập nhật ngắn gọn về doanh số.', NULL, CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset), CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (6, 28, N'Two departments will collaborate on the new campaign.', N'Hai phòng ban sẽ hợp tác trong chiến dịch mới.', NULL, CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset), CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (7, 29, N'Please confirm your attendance by Friday.', N'Vui lòng xác nhận việc tham dự trước thứ Sáu.', NULL, CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset), CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (8, 30, N'The deadline for the report is next Monday.', N'Hạn chót nộp báo cáo là thứ Hai tới.', NULL, CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset), CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (9, 31, N'The supervisor will delegate tasks to the assistants.', N'Giám sát viên sẽ giao việc cho các trợ lý.', NULL, CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset), CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (10, 32, N'We need to discuss the budget before approval.', N'Chúng ta cần thảo luận ngân sách trước khi phê duyệt.', NULL, CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset), CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (11, 33, N'She requested an extension for the project deadline.', N'Cô ấy yêu cầu gia hạn thời hạn dự án.', NULL, CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset), CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (12, 34, N'The follow-up email included the final schedule.', N'Email theo dõi sau đó có kèm lịch trình cuối cùng.', NULL, CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset), CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (13, 35, N'The assistant prepared the minutes after the meeting.', N'Trợ lý đã chuẩn bị biên bản sau cuộc họp.', NULL, CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset), CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (14, 36, N'They decided to postpone the presentation until Thursday.', N'Họ quyết định hoãn bài thuyết trình đến thứ Năm.', NULL, CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset), CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (15, 37, N'The proposal was reviewed by senior management.', N'Bản đề xuất đã được ban quản lý cấp cao xem xét.', NULL, CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset), CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (16, 38, N'I am calling regarding your recent invoice.', N'Tôi gọi về hóa đơn gần đây của bạn.', NULL, CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset), CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (17, 39, N'We had to reschedule the supplier meeting.', N'Chúng tôi đã phải dời lịch họp với nhà cung cấp.', NULL, CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset), CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (18, 40, N'Could you summarize the main points of the report?', N'Bạn có thể tóm tắt các ý chính của báo cáo không?', NULL, CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset), CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (19, 41, N'The venue for the seminar is on the third floor.', N'Địa điểm tổ chức hội thảo nằm ở tầng ba.', NULL, CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset), CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (20, 42, N'The new software improved the team workflow.', N'Phần mềm mới đã cải thiện quy trình làm việc của nhóm.', NULL, CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset), CAST(N'2026-05-18T08:37:06.2275282+07:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (21, 44, N'The company developed a new marketing strategy.', N'Công ty đã phát triển một chiến lược tiếp thị mới.', NULL, CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset), CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (22, 45, N'The company reported strong revenue growth.', N'Công ty báo cáo tăng trưởng doanh thu mạnh.', NULL, CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset), CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (23, 46, N'We estimate the project will cost $50,000.', N'Chúng tôi ước tính dự án sẽ tốn $50,000.', NULL, CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset), CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (24, 47, N'The new system is more efficient than the old one.', N'Hệ thống mới hiệu quả hơn hệ thống cũ.', NULL, CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset), CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (25, 48, N'We need to negotiate the terms of the contract.', N'Chúng ta cần đàm phán các điều khoản hợp đồng.', NULL, CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset), CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (26, 49, N'The company plans to promote its new product.', N'Công ty dự định xúc tiến sản phẩm mới.', NULL, CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset), CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (27, 50, N'The manager must approve the budget.', N'Quản lý phải phê duyệt ngân sách.', NULL, CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset), CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (28, 51, N'We need to purchase new equipment.', N'Chúng tôi cần mua thiết bị mới.', NULL, CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset), CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (29, 52, N'I wake up at 6 AM every day.', N'Tôi thức dậy lúc 6 giờ sáng mỗi ngày.', NULL, CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset), CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (30, 53, N'I usually have toast for breakfast.', N'Tôi thường ăn bánh mì nướng vào bữa sáng.', NULL, CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset), CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (31, 54, N'She commutes to work by train.', N'Cô ấy đi làm bằng tàu hỏa.', NULL, CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset), CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (32, 55, N'I need to buy some groceries for dinner.', N'Tôi cần mua một ít thực phẩm cho bữa tối.', NULL, CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset), CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (33, 56, N'She exercises at the gym three times a week.', N'Cô ấy tập gym ba lần một tuần.', NULL, CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset), CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (34, 57, N'After work, I relax by watching TV.', N'Sau giờ làm, tôi thư giãn bằng cách xem TV.', NULL, CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset), CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (35, 58, N'Reading is my favorite leisure activity.', N'Đọc sách là hoạt động giải trí yêu thích của tôi.', NULL, CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset), CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset))
INSERT [dbo].[ExampleSentences] ([ExampleSentenceID], [WordID], [SentenceText], [SentenceTranslation], [AudioUrl], [CreatedAt], [UpdatedAt]) VALUES (36, 59, N'They share the household chores equally.', N'Họ chia sẻ việc nhà một cách công bằng.', NULL, CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset), CAST(N'2026-06-22T09:16:22.4256507+00:00' AS DateTimeOffset))
